# A class's methods are C functions named after the class, and a class
# name has no length limit. mc_method spelled an instance method from a
# copy of the class's C name cut at 255 bytes, and every name into a slot
# of 600 bytes, while the generated constructor calls the class's
# sp_<Class>_initialize by its whole name: a class whose name passed
# either bound defined one function and called another, and the C did not
# build. These two classes, of 300 and 700 bytes, are reached through
# their class methods.

class 
  def initialize(x) = x.to_s
  def self.make = 7
  def self.twice(n) = make * n
end

class 
  def initialize(x) = x.to_s
  def self.make = 8
end

p .make, .twice(3)
p .make
